const SC: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const tone = (v: number) => (v >= 80 ? "green" : v >= 65 ? "cyan" : "amber");

export function PipelineRow() {
 const { stage, setStage, open, toast } = useCmd();
