 const leakNext = PIPELINE[PIPELINE_LEAK_INDEX + 1];

 return (
 <>
 <Panel span={8} hover title="National Champion Pipeline"
 sub="Population → international level · click a stage to cross-filter"
 right={<Button size="sm" variant="ghost" icon="chart" onClick={() => open("pipeline", null)}>View Pathway Analysis</Button>}>
 <PipelineFunnel stages={PIPELINE} leakIndex={PIPELINE_LEAK_INDEX}
 selected={stage} onSelect={k => { setStage(stage === k ? null : k); toast(stage === k ? "Cleared stage filter" : `Filtered by ${PIPELINE.find(s => s.key === k)?.label}`); }} />
 <div style={{ marginTop: 12 }}>
 <div className="ci-insight" style={{ borderColor: "rgba(255,194,75,0.3)", background: "linear-gradient(120deg, rgba(255,194,75,0.10), rgba(255,194,75,0.02))" }}>
