 <div className="ci-insight__txt">
 <b style={{ color: "var(--ci-amber)" }}>Highest pathway leakage:</b> {leak.label} → {leakNext.label} — only {Math.round((leakNext.value / leak.value) * 100)}% progress ({(leak.value - leakNext.value).toLocaleString()} athletes lost).
 </div>
 </div>
 </div>
 </Panel>

 <Panel span={4} hover title="Future Cycle Readiness" sub="Preparedness across upcoming cycles">
 <div className="cc-cycles">
 {CYCLES.map(c => (
 <div key={c.year} className="cc-cycle" onClick={() => open("cycle", c)} title={`Open ${c.year} readiness`}>
 <div className="cc-cycle__top">
 <span className="cc-cycle__yr">{c.year}</span>
 <span className="cc-cycle__ov" style={{ color: SC[tone(c.overall)] }}>{c.overall}%</span>
 </div>
 {c.dims.slice(0, 3).map(d => <Bullet key={d.label} label={d.label} value={d.value} />)}
 <div className="ci-faint" style={{ fontSize: 10, marginTop: 4 }}>{c.headline}</div>
 </div>
 ))}
 </div>
 </Panel>
 </>
 );
}
","import React from "react";
import { RegionT } from "../../data/command";

const FLAG: Record<string, string> = { green: "#12a06d", amber: "#d9820a", red: "#e5484d", cyan: "#0a99c7" };
export type MapLayer = "density" | "participation" | "highpotential" | "assessments";

// Dependency-free interactive geographic map: real lat/lng projection, pan + zoom,
// layer toggles, hover tooltips, clustering count bubbles and region selection.
// (Renders fully offline — no external tile/CDN requests.)
export function TalentMapLeaflet({ regions, layer, selected, onSelect }:
 { regions: RegionT[]; layer: MapLayer; selected: string | null; onSelect: (k: string) => void }) {
 const W = 400, H = 320;
 const latMin = 50.2, latMax = 58.0, lngMin = -5.0, lngMax = 2.1;
 const px = (lng: number) => ((lng - lngMin) / (lngMax - lngMin)) * W;
 const py = (lat: number) => ((latMax - lat) / (latMax - latMin)) * H;

 const [view, setView] = React.useState({ k: 1, tx: 0, ty: 0 });
 const drag = React.useRef<{ x: number; y: number; tx: number; ty: number } | null>(null);
 const [tip, setTip] = React.useState<{ x: number; y: number; r: RegionT } | null>(null);

 const metric = (r: RegionT) =>
 layer === "density" ? r.discovered : layer === "participation" ? r.assessed :
 layer === "highpotential" ? r.highPotential : r.pathways;
 const max = Math.max(...regions.map(metric));
 const cluster = layer === "highpotential" || layer === "assessments";

 const zoom = (f: number) => setView(v => ({ ...v, k: Math.min(4, Math.max(1, +(v.k * f).toFixed(2))) }));
 const onWheel = (e: React.WheelEvent) => { e.preventDefault(); zoom(e.deltaY < 0 ? 1.2 : 1 / 1.2); };
 const onDown = (e: React.PointerEvent) => { drag.current = { x: e.clientX, y: e.clientY, tx: view.tx, ty: view.ty }; (e.target as Element).setPointerCapture?.(e.pointerId); };
 const onMove = (e: React.PointerEvent) => {
 if (!drag.current) return;
 setView(v => ({ ...v, tx: drag.current!.tx + (e.clientX - drag.current!.x), ty: drag.current!.ty + (e.clientY - drag.current!.y) }));
 };
 const onUp = () => { drag.current = null; };

 // stylized landmass silhouette (decorative base)
 const land = "M150,26 C205,10 250,34 246,70 C286,72 300,120 268,150 C300,180 280,236 232,242 C224,286 168,300 138,270 C96,286 60,252 74,212 C40,196 44,140 84,120 C70,86 104,44 150,26 Z";

 return (
 <div className="cc-mapbox" onWheel={onWheel} onPointerDown={onDown} onPointerMove={onMove}
 onPointerUp={onUp} onPointerLeave={() => { onUp(); setTip(null); }} style={{ cursor: drag.current ? "grabbing" : "grab" }}>
 <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", height: "100%", display: "block" }}>
 <defs>
 <radialGradient id="mapglow" cx="46%" cy="40%" r="65%">
 <stop offset="0%" stopColor="rgba(10,153,199,0.10)" />
 <stop offset="100%" stopColor="rgba(18,38,78,0.04)" />
 </radialGradient>
 </defs>
 <rect x="0" y="0" width={W} height={H} fill="#e7edf5" />
 {/* graticule */}
 {Array.from({ length: 9 }, (_, i) => <line key={"gv" + i} x1={(W / 8) * i} y1="0" x2={(W / 8) * i} y2={H} stroke="rgba(18,38,78,0.05)" />)}
 {Array.from({ length: 8 }, (_, i) => <line key={"gh" + i} x1="0" y1={(H / 7) * i} x2={W} y2={(H / 7) * i} stroke="rgba(18,38,78,0.05)" />)}

 <g transform={`translate(${view.tx},${view.ty}) scale(${view.k})`} style={{ transition: drag.current ? "none" : "transform .18s ease" }}>
 <path d={land} fill="url(#mapglow)" stroke="rgba(18,38,78,0.22)" strokeWidth="1" />

 {regions.map(r => {
 const c = FLAG[r.flag], sel = selected === r.key, t = metric(r) / max;
 const x = px(r.lng), y = py(r.lat);
 return (
 <g key={r.key} style={{ cursor: "pointer" }}
 onClick={e => { e.stopPropagation(); onSelect(r.key); }}
 onPointerMove={e => setTip({ x: e.clientX, y: e.clientY, r })}
 onPointerLeave={() => setTip(null)}>
 {!cluster && <circle cx={x} cy={y} r={(10 + t * 26) / view.k} fill={c} opacity="0.14" />}
 {!cluster && (
 <circle cx={x} cy={y} r={(4 + t * 9) / view.k} fill={c} fillOpacity="0.9"
 stroke="#fff" strokeWidth={(sel ? 2.4 : 1.4) / view.k} />
 )}
 {cluster && (
 <>
 <circle cx={x} cy={y} r={(13 + t * 12) / view.k} fill={c} stroke="#fff"
 strokeWidth={(sel ? 3 : 2) / view.k} style={{ filter: "drop-shadow(0 1px 2px rgba(18,38,78,.3))" }} />
 <text x={x} y={y + 3 / view.k} textAnchor="middle" fontSize={11 / view.k} fontWeight="800" fill="#fff">{metric(r)}</text>
 </>
 )}
 <text x={x} y={y - (cluster ? 15 + t * 12 : 12 + t * 26) / view.k - 3 / view.k} textAnchor="middle"
 fontSize={9 / view.k} fontWeight="700" fill="#10213f">{r.name}</text>
 </g>
 );
 })}
 </g>
 </svg>

 {/* zoom controls */}
 <div style={{ position: "absolute", top: 8, right: 8, display: "flex", flexDirection: "column", gap: 4 }}>
 {[["+", () => zoom(1.3)], ["–", () => zoom(1 / 1.3)], ["⟲", () => setView({ k: 1, tx: 0, ty: 0 })]].map(([lbl, fn]: any) => (
 <button key={lbl} onClick={e => { e.stopPropagation(); fn(); }} onPointerDown={e => e.stopPropagation()}
 style={{ width: 26, height: 26, borderRadius: 7, border: "1px solid var(--ci-border-strong)", background: "#fff",
 color: "var(--ci-text)", fontSize: 14, fontWeight: 700, cursor: "pointer", lineHeight: 1 }}>{lbl}</button>
 ))}
 </div>

 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 12, top: tip.y - 10 }}>
 <b>{tip.r.name}</b><br />
 <span className="ci-faint">{metric(tip.r).toLocaleString()} {layer === "density" ? "discovered" : layer === "participation" ? "assessed" : layer === "highpotential" ? "high-potential" : "pathways"} · {tip.r.conversion}% conversion</span>
 </div>
 )}
 </div>
 );
}
","import React from "react";
import { VeloPt } from "../../data/command";

const SPORT_COLOR: Record<string, string> = {
 Athletics: "#0a99c7", Swimming: "#12a06d", Taekwondo: "#7c5cff", Cycling: "#d9820a",
 Rowing: "#0bb39a", Judo: "#2f6fed", default: "#8092ad",
};
const initials = (n: string) => n.replace(/[^A-Za-z. ]/g, "").split(/[.\s]+/).filter(Boolean).map(w => w[0]).slice(0, 2).join("").toUpperCase();

// Enlarged quadrant bubble: X = performance, Y = improvement, size = confidence
export function VelocityScatter({ points, onSelect }:
 { points: VeloPt[]; onSelect: (p: VeloPt) => void }) {
 const [tip, setTip] = React.useState<{ x: number; y: number; p: VeloPt } | null>(null);
 const w = 640, h = 360, pad = 40;
 const X = (v: number) => pad + (v / 100) * (w - pad * 2);
 const Y = (v: number) => h - pad - (v / 100) * (h - pad * 2);
 const midX = X(50), midY = Y(50);

 const quad = (x: number, y: number, anchor: string, label: string, color: string, strong = false) => (
 <text x={x} y={y} textAnchor={anchor as any} fontSize="10.5" fontWeight="800" fill={color} opacity={strong ? 0.95 : 0.5} letterSpacing="0.04em">{label}</text>
 );

 return (
 <div style={{ position: "relative" }}>
 <svg className="ci-chart" viewBox={`0 0 ${w} ${h}`} onMouseLeave={() => setTip(null)}>
 {/* emerging / high-growth quadrant (top-left) highlight */}
 <rect x={pad} y={pad} width={midX - pad} height={midY - pad} rx="8" fill="rgba(10,153,199,0.08)" stroke="rgba(10,153,199,0.30)" strokeDasharray="5 4" />
 <line x1={midX} y1={pad} x2={midX} y2={h - pad} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={midY} x2={w - pad} y2={midY} stroke="var(--ci-grid-line)" />
 <line x1={pad} y1={pad} x2={pad} y2={h - pad} stroke="var(--ci-border)" />
 <line x1={pad} y1={h - pad} x2={w - pad} y2={h - pad} stroke="var(--ci-border)" />

 {quad(pad + 10, pad + 18, "start", "EMERGING · HIGH GROWTH", "#0a99c7", true)}
 {quad(w - pad - 8, pad + 18, "end", "HIGH PERFORMANCE · HIGH GROWTH", "#45577a")}
 {quad(pad + 10, h - pad - 10, "start", "DEVELOPMENT REQUIRED", "#45577a")}
 {quad(w - pad - 8, h - pad - 10, "end", "HIGH PERFORMANCE · LOW GROWTH", "#45577a")}

 <text x={w / 2} y={h - 6} textAnchor="middle">Current performance level →</text>
 <text x={13} y={h / 2} textAnchor="middle" transform={`rotate(-90 13 ${h / 2})`}>Rate of improvement →</text>

 {points.map(p => {
 const emerging = p.perf < 50 && p.growth > 50;
 const c = SPORT_COLOR[p.sport] || SPORT_COLOR.default;
 return (
 <circle key={p.id} cx={X(p.perf)} cy={Y(p.growth)} r={5 + (p.conf / 100) * 11}
 fill={c} fillOpacity={emerging ? 0.7 : 0.42} stroke={c} strokeWidth={emerging ? 2 : 1.2}
 style={{ cursor: "pointer", filter: emerging ? `drop-shadow(0 2px 5px ${c}66)` : "none" }}
 onMouseMove={e => setTip({ x: e.clientX, y: e.clientY, p })}
 onClick={() => onSelect(p)} />
 );
 })}
 </svg>
 {tip && (
 <div className="ci-tip__pop" style={{ left: tip.x + 14, top: tip.y - 12, minWidth: 190, pointerEvents: "none" }}>
 <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 6 }}>
 <span style={{ width: 30, height: 30, borderRadius: 9, background: SPORT_COLOR[tip.p.sport] || SPORT_COLOR.default,
 color: "#fff", display: "grid", placeItems: "center", fontSize: 11, fontWeight: 800, flex: "none" }}>{initials(tip.p.name)}</span>
 <div style={{ lineHeight: 1.25 }}>
 <b>{tip.p.name}</b><br />
 <span className="ci-faint" style={{ fontSize: 10.5 }}>{tip.p.sport} · age {tip.p.age} · {tip.p.stage}</span>
 </div>
 </div>
 <div style={{ display: "flex", gap: 12, fontSize: 11 }}>
 <span className="ci-faint">Percentile <b style={{ color: "var(--ci-text)" }}>P{tip.p.perf}</b></span>
 <span className="ci-faint">Improvement <b style={{ color: "var(--ci-green)" }}>+{tip.p.growth}%</b></span>
 </div>
 </div>
 )}
 </div>
 );
}
","import React from "react";
import { Panel } from "../../primitives";
import { Chip } from "../../KpiCard";
import { Button, ActionRow } from "../../Button";
import { TalentMapLeaflet, MapLayer } from "../../charts/TalentMapLeaflet";
import { VelocityScatter } from "../../charts/velocity";
import { REGIONS_T, VELOCITY, NATIONAL_CONVERSION_AVG } from "../../../data/command";
import { useCmd } from "./ctx";

const LAYERS: { id: MapLayer; label: string }[] = [
 { id: "density", label: "Talent Density" },
 { id: "participation", label: "Participation" },
 { id: "highpotential", label: "High Potential" },
 { id: "assessments", label: "Assessments" },
];

export function MapRow() {
 const { region, setRegion, open, toast } = useCmd();
 const [layer, setLayer] = React.useState<MapLayer>("density");
 const sel = REGIONS_T.find(r => r.key === region) || null;

 return (
 <Panel span={7} hover title="National Talent Opportunity"
 sub="Live OpenStreetMap · talent density, participation, high potential & assessment activity">
 <div className="cc-map-toggles">
 <div className="ci-seg">
 {LAYERS.map(l => (
 <button key={l.id} className={`ci-seg__btn ${layer === l.id ? "ci-seg__btn--active" : ""}`}
 onClick={() => setLayer(l.id)}>{l.label}</button>
 ))}
 </div>
 </div>
 <div className="cc-map-wrap">
 <div className="cc-map">
 <TalentMapLeaflet regions={REGIONS_T} layer={layer} selected={region}
 onSelect={k => { setRegion(region === k ? null : k); toast(region === k ? "Cleared region filter" : `Region · ${REGIONS_T.find(r => r.key === k)?.name}`); }} />
 </div>
 <div className="cc-snapshot">
 <div className="ci-eyebrow" style={{ marginBottom: 8 }}>Regional Snapshot</div>
 {!sel && <div className="ci-faint" style={{ fontSize: 12, lineHeight: 1.5 }}>Select a region marker to see assessed profiles, high-potential count, pathways, conversion, top sports and emerging opportunities.</div>}
 {sel && (
 <>
 <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 2 }}>
 <span style={{ fontSize: 15, fontWeight: 800 }}>{sel.name}</span>
 <Chip status={sel.flag}>{sel.conversion}% conversion</Chip>
 </div>
 <div className="cc-snap__grid">
 <div><div className="cc-snap__v ci-num">{sel.assessed.toLocaleString()}</div><div className="cc-snap__l">Profiles assessed</div></div>
 <div><div className="cc-snap__v ci-num">{sel.highPotential}</div><div className="cc-snap__l">High potential</div></div>
 <div><div className="cc-snap__v ci-num">{sel.pathways.toLocaleString()}</div><div className="cc-snap__l">Dev pathways</div></div>
 <div><div className="cc-snap__v">{sel.fastest}</div><div className="cc-snap__l">Top sport</div></div>
 </div>
 <div className="ci-insight" style={{ marginBottom: 10 }}>
 <span className="ci-insight__icon">◆</span>
 <div className="ci-insight__txt" style={{ fontSize: 11.5 }}>{sel.insight}
 {sel.conversion < NATIONAL_CONVERSION_AVG && <> <b>({(NATIONAL_CONVERSION_AVG - sel.conversion).toFixed(1)}pts below national avg)</b></>}</div>
 </div>
 <ActionRow actions={["Investigate", "Create Assessment", "Add to Watchlist"]}
 onAction={a => { if (a === "Investigate") open("region", sel); else toast(`${a} — ${sel.name}`); }} />
 </>
 )}
 </div>
 </div>
 </Panel>
 );
}

